SELECT signup_month, credit_limit_bucket, tokyo_count FROM (SELECT DATE_TRUNC('MONTH', signup_date) AS signup_month, CASE WHEN credit_limit >= 16700 THEN 'high' WHEN credit_limit >= 6800 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, SUM(CASE WHEN city = 'Tokyo' THEN 1 ELSE 0 END) AS tokyo_count FROM customers GROUP BY DATE_TRUNC('MONTH', signup_date), CASE WHEN credit_limit >= 16700 THEN 'high' WHEN credit_limit >= 6800 THEN 'mid' ELSE 'low' END) AS sub WHERE tokyo_count >= 27 ORDER BY signup_month;
